CREATE FUNCTION public.beacon_access_level(p_beacon_id text, p_viewer_id text) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
SELECT CASE
  WHEN r & 1 <> 0 THEN 0
  WHEN r & 6 <> 0 THEN 1
  WHEN r & 248 <> 0 THEN 2
  ELSE 3
END
FROM (SELECT public.beacon_access_reasons(p_beacon_id, p_viewer_id) AS r) s;
$$
''',

  r'''
CREATE FUNCTION public.beacon_access_reasons(p_beacon_id text, p_viewer_id text) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
RETURN COALESCE((
  SELECT CASE
    WHEN nullif(btrim(coalesce(p_viewer_id, '')), '') IS NULL THEN 0
    WHEN public.block_hides(b.user_id, p_viewer_id) THEN 0
    WHEN b.status = 3 THEN CASE WHEN b.user_id = p_viewer_id THEN 1 ELSE 0 END
    WHEN b.status = 2 THEN 0
    ELSE
        (CASE WHEN b.user_id = p_viewer_id THEN 1 ELSE 0 END)
      | (CASE WHEN EXISTS (
            SELECT 1 FROM public.beacon_steward bs
            WHERE bs.beacon_id = b.id AND bs.user_id = p_viewer_id
          ) OR EXISTS (
            SELECT 1 FROM public.beacon_participant bp
            WHERE bp.beacon_id = b.id AND bp.user_id = p_viewer_id AND bp.role = 1
          ) THEN 2 ELSE 0 END)
      | (CASE WHEN EXISTS (
            SELECT 1 FROM public.beacon_participant bp
            WHERE bp.beacon_id = b.id AND bp.user_id = p_viewer_id AND bp.room_access = 3
          ) THEN 4 ELSE 0 END)
      | (CASE WHEN EXISTS (
            SELECT 1 FROM public.beacon_forward_edge fe
            WHERE fe.beacon_id = b.id AND fe.recipient_id = p_viewer_id
              AND fe.cancelled_at IS NULL
          ) THEN 8 ELSE 0 END)
      | (CASE WHEN EXISTS (
            SELECT 1 FROM public.beacon_help_offer ho
            WHERE ho.beacon_id = b.id AND ho.user_id = p_viewer_id AND ho.status = 0
          ) THEN 16 ELSE 0 END)
      | (CASE WHEN b.is_discoverable
            AND b.status IN (0, 7, 8)
            AND b.published_at IS NOT NULL
            AND b.user_id IS NOT NULL
            AND public.person_are_mutually_visible_cached(p_viewer_id, b.user_id, '')
          THEN 32 ELSE 0 END)
      -- Same bounded beacon_member probes as beacon_can_read_content above.
      | (CASE WHEN b.parent_beacon_id IS NOT NULL AND b.published_at IS NOT NULL
            AND EXISTS (
                SELECT 1 FROM public.beacon member_beacon
                WHERE member_beacon.id = b.parent_beacon_id
                  AND member_beacon.status NOT IN (2, 3)
                  AND member_beacon.published_at IS NOT NULL
                  AND (
                    (member_beacon.user_id IS NOT NULL
                      AND member_beacon.user_id = p_viewer_id)
                    OR CASE WHEN
                      EXISTS (
                        SELECT 1 FROM public.beacon_steward bs
                        WHERE bs.beacon_id = member_beacon.id
                          AND bs.user_id = p_viewer_id
                      )
                      OR EXISTS (
                        SELECT 1 FROM public.beacon_participant bp
                        WHERE bp.beacon_id = member_beacon.id
                          AND bp.user_id = p_viewer_id
                          AND (bp.role = 1 OR bp.room_access = 3)
                      )
                      THEN NOT public.block_hides(member_beacon.user_id, p_viewer_id)
                      ELSE false
                    END
                  )
            )
          THEN 64 ELSE 0 END)
      | (CASE WHEN b.published_at IS NOT NULL
            AND EXISTS (
                SELECT 1 FROM public.beacon_ancestor a
                JOIN public.beacon member_beacon ON member_beacon.id = a.beacon_id
                WHERE a.ancestor_id = b.id
                  AND member_beacon.status NOT IN (2, 3)
                  AND member_beacon.published_at IS NOT NULL
                  AND (
                    (member_beacon.user_id IS NOT NULL
                      AND member_beacon.user_id = p_viewer_id)
                    OR CASE WHEN
                      EXISTS (
                        SELECT 1 FROM public.beacon_steward bs
                        WHERE bs.beacon_id = member_beacon.id
                          AND bs.user_id = p_viewer_id
                      )
                      OR EXISTS (
                        SELECT 1 FROM public.beacon_participant bp
                        WHERE bp.beacon_id = member_beacon.id
                          AND bp.user_id = p_viewer_id
                          AND (bp.role = 1 OR bp.room_access = 3)
                      )
                      THEN NOT public.block_hides(member_beacon.user_id, p_viewer_id)
                      ELSE false
                    END
                  )
            )
          THEN 128 ELSE 0 END)
  END
  FROM public.beacon b
  WHERE b.id = p_beacon_id
), 0);
END;
$$
''',

  r'''
CREATE FUNCTION public.beacon_ancestor_on_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.parent_beacon_id IS NULL THEN
    RETURN NEW;
  END IF;
  INSERT INTO public.beacon_ancestor (beacon_id, ancestor_id, depth)
  SELECT NEW.id, NEW.parent_beacon_id, 1
  UNION ALL
  SELECT NEW.id, a.ancestor_id, a.depth + 1
  FROM public.beacon_ancestor a
  WHERE a.beacon_id = NEW.parent_beacon_id
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$
''',

  r'''
CREATE FUNCTION public.beacon_apply_inbox_before_response_tombstone() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'UPDATE' OR NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  PERFORM set_config('tentura.allow_inbox_tombstone_transition', '1', true);

  -- Open-family {0,7,8} -> terminal lifecycle (cancelled, reviewOpen, closed).
  IF NEW.status IN (1, 5, 6) AND OLD.status IN (0, 7, 8) THEN
    UPDATE public.inbox_item ii
    SET
      status = 3,
      before_response_terminal_at = coalesce(
        ii.before_response_terminal_at,
        now()
      )
    WHERE ii.beacon_id = NEW.id
      AND ii.status = 0
      AND NOT EXISTS (
        SELECT 1
        FROM public.beacon_help_offer ho
        WHERE ho.beacon_id = ii.beacon_id
          AND ho.user_id = ii.user_id
          AND ho.status = 0
      );
  END IF;

  IF NEW.status = 2 THEN
    UPDATE public.inbox_item ii
    SET
      status = 4,
      before_response_terminal_at = coalesce(
        ii.before_response_terminal_at,
        now()
      )
    WHERE ii.beacon_id = NEW.id
      AND ii.status IN (0, 3)
      AND NOT EXISTS (
        SELECT 1
        FROM public.beacon_help_offer ho
        WHERE ho.beacon_id = ii.beacon_id
          AND ho.user_id = ii.user_id
          AND ho.status = 0
      );
  END IF;

  IF OLD.status = 5 AND NEW.status = 6 THEN
    UPDATE public.inbox_item ii
    SET
      status = 3,
      before_response_terminal_at = coalesce(
        ii.before_response_terminal_at,
        now()
      )
    WHERE ii.beacon_id = NEW.id
      AND ii.status IN (0, 1)
      AND EXISTS (
        SELECT 1
        FROM public.beacon_help_offer ho
        WHERE ho.beacon_id = ii.beacon_id
          AND ho.user_id = ii.user_id
          AND ho.status = 1
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.beacon_help_offer ho
        WHERE ho.beacon_id = ii.beacon_id
          AND ho.user_id = ii.user_id
          AND ho.status = 0
      );
  END IF;

  -- Reopen from Wrapping up (5 -> open-family): revert the open->5 tombstone.
  IF OLD.status = 5 AND NEW.status IN (0, 7, 8) THEN
    UPDATE public.inbox_item ii
    SET
      status = 0,
      before_response_terminal_at = NULL,
      tombstone_dismissed_at = NULL
    WHERE ii.beacon_id = NEW.id
      AND ii.status = 3
      AND NOT EXISTS (
        SELECT 1
        FROM public.beacon_help_offer ho
        WHERE ho.beacon_id = ii.beacon_id
          AND ho.user_id = ii.user_id
          AND ho.status = 0
      );
  END IF;

  RETURN NEW;
END;
$$
''',

  r'''
