  r'''
CREATE TABLE public.beacon (
    id text DEFAULT concat('B', "substring"((gen_random_uuid())::text, '\w{12}'::text)) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    user_id text,
    title text NOT NULL,
    description text NOT NULL,
    lat double precision,
    long double precision,
    context text,
    ticker integer DEFAULT 0 NOT NULL,
    start_at timestamp with time zone,
    end_at timestamp with time zone,
    tags text DEFAULT ''::text NOT NULL,
    status smallint DEFAULT 0 NOT NULL,
    status_changed_at timestamp with time zone,
    needs text DEFAULT ''::text NOT NULL,
    lineage_parent_beacon_id text,
    lineage_root_beacon_id text,
    address_label text,
    primary_need_slug text,
    cover_image_id uuid,
    cover_source smallint DEFAULT 0 NOT NULL,
    cover_thumb_image_id uuid,
    review_reopen_count smallint DEFAULT 0 NOT NULL,
    parent_beacon_id text,
    published_at timestamp with time zone,
    hierarchy_event_sequence bigint DEFAULT 0 NOT NULL,
    is_discoverable boolean DEFAULT true NOT NULL,
    CONSTRAINT beacon__description_len CHECK ((char_length(description) <= 2048)),
    CONSTRAINT beacon__title_len CHECK ((char_length(title) <= 128)),
    CONSTRAINT beacon_context_name_length CHECK (((char_length(context) >= 3) AND (char_length(context) <= 32))),
    CONSTRAINT beacon_cover_source_ck CHECK ((cover_source = ANY (ARRAY[0, 1]))),
    CONSTRAINT beacon_owner_or_deleted_ck CHECK (((user_id IS NOT NULL) OR (status = 2))),
    CONSTRAINT beacon_primary_need_membership_ck CHECK ((((needs = ''::text) AND (primary_need_slug IS NULL)) OR ((needs <> ''::text) AND (primary_need_slug IS NOT NULL) AND (primary_need_slug = ANY (regexp_split_to_array(needs, '\s*,\s*'::text)))))),
    CONSTRAINT beacon_status_range CHECK ((status = ANY (ARRAY[0, 1, 2, 3, 5, 6, 7, 8])))
)
''',

  r'''
COMMENT ON COLUMN public.beacon.status IS '0=open, 1=cancelled, 2=deleted, 3=draft, 5=reviewOpen, 6=closed, 7=needsMoreHelp, 8=enoughHelp'

''',

  r'''
COMMENT ON COLUMN public.beacon.parent_beacon_id IS 'Immutable nesting parent (distinct from lineage_parent_beacon_id). Assigned on insert only.'

