  r'''
CREATE FUNCTION public.beacon_parent_beacon_id_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  parent_row public.beacon%ROWTYPE;
  cycle_hit text;
BEGIN
  IF NEW.parent_beacon_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.parent_beacon_id = NEW.id THEN
    RAISE EXCEPTION 'beacon_parent_self_reference'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO parent_row FROM public.beacon WHERE id = NEW.parent_beacon_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'beacon_parent_missing'
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  IF parent_row.published_at IS NULL OR parent_row.status = 3 THEN
    RAISE EXCEPTION 'beacon_parent_not_published'
      USING ERRCODE = 'check_violation';
  END IF;

  WITH RECURSIVE ancestors AS (
    SELECT id, parent_beacon_id
    FROM public.beacon
    WHERE id = NEW.parent_beacon_id
    UNION ALL
    SELECT b.id, b.parent_beacon_id
    FROM public.beacon b
    JOIN ancestors a ON b.id = a.parent_beacon_id
    WHERE a.parent_beacon_id IS NOT NULL
  )
  SELECT id INTO cycle_hit
  FROM ancestors
  WHERE id = NEW.id
  LIMIT 1;

  IF cycle_hit IS NOT NULL THEN
    RAISE EXCEPTION 'beacon_parent_cycle'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$
''',

  r'''
CREATE FUNCTION public.beacon_parent_beacon_id_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.parent_beacon_id IS DISTINCT FROM OLD.parent_beacon_id THEN
    RAISE EXCEPTION 'beacon_parent_immutable'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$
''',

  r'''
CREATE FUNCTION public.beacon_promotions_consistency_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  child_parent text;
  source_beacon text;
  source_thread text;
BEGIN
  SELECT parent_beacon_id INTO child_parent
  FROM public.beacon
  WHERE id = NEW.child_beacon_id;

  IF child_parent IS DISTINCT FROM NEW.parent_beacon_id THEN
    RAISE EXCEPTION 'beacon_promotion_parent_mismatch'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.source_message_id IS NOT NULL THEN
    SELECT beacon_id, thread_item_id
    INTO source_beacon, source_thread
    FROM public.beacon_room_message
    WHERE id = NEW.source_message_id;

    IF source_beacon IS DISTINCT FROM NEW.parent_beacon_id THEN
      RAISE EXCEPTION 'beacon_promotion_source_beacon_mismatch'
        USING ERRCODE = 'check_violation';
    END IF;

    IF source_thread IS NOT NULL THEN
      RAISE EXCEPTION 'beacon_promotion_source_not_general'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$
''',

  r'''
CREATE FUNCTION public.beacon_room_message_general_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.thread_item_id IS DISTINCT FROM OLD.thread_item_id THEN
    IF NEW.thread_item_id IS NOT NULL
      AND NOT public.discussion_internal_fixture_allowed() THEN
      RAISE EXCEPTION 'discussion_scope_disabled'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$
''',

  r'''
CREATE FUNCTION public.beacon_room_message_lifecycle_write_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  beacon_status smallint;
BEGIN
  IF NEW.system_message_kind IS NOT NULL OR NEW.author_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF public.discussion_internal_fixture_allowed() THEN
    RETURN NEW;
  END IF;

  SELECT b.status
  INTO beacon_status
  FROM public.beacon b
  WHERE b.id = NEW.beacon_id;

  IF beacon_status IN (1, 2, 6) THEN
    RAISE EXCEPTION 'discussion_read_only'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$
''',

