  r'''
CREATE FUNCTION public.block_cascade_candidates(_blocker text, _root text, _mode smallint, _max_depth integer, _limit integer) RETURNS TABLE(user_id text, depth integer)
    LANGUAGE sql STABLE
    AS $$
WITH RECURSIVE sub AS (
  SELECT g.descendant_node_key AS k, g.descendant_user_id AS uid, 1 AS depth
  FROM public.invite_genealogy g
  WHERE g.ancestor_user_id = _root
  UNION ALL
  SELECT g.descendant_node_key, g.descendant_user_id, s.depth + 1
  FROM public.invite_genealogy g
  JOIN sub s ON g.ancestor_node_key = s.k
  WHERE s.depth < _max_depth
    -- never descend through the blocker: everything below them is their own
    -- invite subtree
    AND s.uid IS DISTINCT FROM _blocker
    -- descend through deleted (anonymized) nodes unconditionally; the tree
    -- structure survives account deletion even though uid becomes NULL
    AND (s.uid IS NULL
         OR public.block_cascade_unattached(_blocker, _root, s.uid))
)
SELECT s.uid, min(s.depth)::int
FROM sub s
WHERE s.uid IS NOT NULL
  AND s.uid <> _blocker
  AND public.block_cascade_unattached(_blocker, _root, s.uid)
GROUP BY s.uid
ORDER BY 2, 1
LIMIT _limit;
$$
''',

  r'''
CREATE FUNCTION public.block_cascade_unattached(_blocker text, _root text, _candidate text) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT CASE WHEN _candidate = _blocker THEN false ELSE NOT (
    -- (a) the blocker mutually trusts the candidate themselves
    EXISTS (
      SELECT 1
      FROM public.vote_user m_out
      JOIN public.vote_user m_in
        ON m_in.subject = _candidate AND m_in.object = _blocker
      WHERE m_out.subject = _blocker AND m_out.object = _candidate
        AND m_out.amount > 0 AND m_in.amount > 0)
    -- (b) or someone the blocker mutually trusts vouches for the candidate
    OR EXISTS (
      SELECT 1
      FROM public.vote_user v_out
      JOIN public.vote_user v_in
        ON v_in.subject = v_out.object AND v_in.object = _candidate
      WHERE v_out.subject = _candidate
        AND v_out.amount > 0 AND v_in.amount > 0
        AND v_out.object <> _root
        AND v_out.object <> _blocker
        AND NOT EXISTS (
          SELECT 1 FROM public.user_block ub
          WHERE ub.blocker_id = _blocker AND ub.blocked_id = v_out.object)
        AND EXISTS (
          SELECT 1 FROM public.vote_user b_out
          JOIN public.vote_user b_in
            ON b_in.subject = b_out.object AND b_in.object = _blocker
          WHERE b_out.subject = _blocker AND b_out.object = v_out.object
            AND b_out.amount > 0 AND b_in.amount > 0))
  ) END;
$$
''',

  r'''
CREATE FUNCTION public.block_hides(_a text, _b text) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.user_block WHERE blocker_id = _a AND blocked_id = _b)
      OR EXISTS (SELECT 1 FROM public.user_block WHERE blocker_id = _b AND blocked_id = _a);
$$
''',

  r'''
CREATE FUNCTION public.bridge_attention_room_seen(p_account_id text, p_beacon_id text, p_thread_item_id text, p_last_seen_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  updated_count integer;
BEGIN
  UPDATE public.notification_outbox n
  SET seen_at = COALESCE(n.seen_at, now())
  WHERE n.account_id = p_account_id
    AND n.beacon_id = p_beacon_id
    AND n.coordination_item_id IS NOT DISTINCT FROM p_thread_item_id
    AND n.destination_kind = 'beacon_room_message'
    AND n.seen_at IS NULL
    AND EXISTS (
      SELECT 1
      FROM public.beacon_room_message message
      WHERE message.id = n.target_entity_id
        AND message.beacon_id = p_beacon_id
        AND message.thread_item_id IS NOT DISTINCT FROM p_thread_item_id
        AND message.created_at <= p_last_seen_at
    );

  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$$
''',

  r'''
CREATE FUNCTION public.bridge_attention_room_seen_trigger() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.last_seen_at > OLD.last_seen_at THEN
    PERFORM public.bridge_attention_room_seen(
      NEW.user_id,
      NEW.beacon_id,
      NEW.thread_item_id,
      NEW.last_seen_at
    );
  END IF;
  RETURN NULL;
END;
$$
''',

  r'''
CREATE FUNCTION public.bump_constellation_anchor_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  _viewer_id text;
  _new_revision bigint;
  _new_placed timestamptz;
BEGIN
  IF TG_OP = 'DELETE' THEN
    _viewer_id := OLD.viewer_id;
    UPDATE public.constellation_anchor_cursor c
       SET revision = c.revision + 1
     WHERE c.viewer_id = _viewer_id
     RETURNING c.revision INTO _new_revision;
    IF NOT FOUND THEN
      RETURN OLD;
    END IF;
    RETURN OLD;
  END IF;

  _viewer_id := NEW.viewer_id;

  UPDATE public.constellation_anchor_cursor c
     SET
       revision = c.revision + 1,
       last_placed_at = greatest(
         clock_timestamp(),
         COALESCE(c.last_placed_at, '-infinity'::timestamptz) + interval '1 microsecond'
       )
   WHERE c.viewer_id = _viewer_id
   RETURNING c.revision, c.last_placed_at INTO _new_revision, _new_placed;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'constellation_anchor_cursor missing for viewer %', _viewer_id;
  END IF;

  NEW.revision := _new_revision;
  NEW.placed_at := _new_placed;
  RETURN NEW;
END;
$$
''',

  r'''
