  r'''
CREATE FUNCTION public.cap_strength(_s double precision, _k double precision, _anchor timestamp with time zone, _half_life_seconds double precision) RETURNS double precision
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN _s <= 0 THEN 0 ELSE
    (_s * pow(2, -extract(epoch FROM (now() - _anchor)) / _half_life_seconds))
    / (_k + _s * pow(2, -extract(epoch FROM (now() - _anchor)) / _half_life_seconds))
  END;
$$
''',

