  r'''
CREATE FUNCTION public.discussion_internal_fixture_allowed() RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
-- COALESCE guards against an unset GUC: current_setting(name, true) returns
-- NULL when never SET, and `NULL = 'allow_non_general'` is NULL (not false),
-- which PL/pgSQL's IF treats as false and silently skips the RAISE entirely
-- -- i.e. without this, the guard is inert in every ordinary session.
SELECT COALESCE(
  current_setting('tentura.discussion_internal_fixture', true),
  ''
) = 'allow_non_general';
$$
''',

  r'''
CREATE FUNCTION public.emit_realtime_entity_change(p_entity text, p_id text, p_event text, p_user_ids text[], p_extra jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  normalized_user_ids text[];
  actor_user_id text;
  recipient_index integer := 1;
  recipient_count integer;
  take_count integer;
  recipient_chunk text[];
  payload text;
BEGIN
  IF p_entity IS NULL OR p_entity = ''
     OR p_id IS NULL OR p_id = ''
     OR p_event NOT IN ('insert', 'update', 'delete') THEN
    RAISE WARNING 'emit_realtime_entity_change: invalid envelope for kind %',
      COALESCE(p_entity, '<null>');
    RETURN;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT user_id ORDER BY user_id), ARRAY[]::text[])
  INTO normalized_user_ids
  FROM unnest(COALESCE(p_user_ids, ARRAY[]::text[])) AS user_id
  WHERE user_id IS NOT NULL AND user_id <> '';

  IF cardinality(normalized_user_ids) = 0 THEN
    RETURN;
  END IF;

  actor_user_id := NULLIF(
    current_setting('tentura.mutating_user_id', true),
    ''
  );
  recipient_count := cardinality(normalized_user_ids);

  WHILE recipient_index <= recipient_count LOOP
    take_count := LEAST(100, recipient_count - recipient_index + 1);

    LOOP
      recipient_chunk := normalized_user_ids[
        recipient_index:recipient_index + take_count - 1
      ];
      payload := jsonb_strip_nulls(
        jsonb_build_object(
          'event', p_event,
          'entity', p_entity,
          'id', p_id,
          'user_ids', to_jsonb(recipient_chunk),
          'actor_user_id', actor_user_id
        ) || COALESCE(p_extra, '{}'::jsonb)
      )::text;

      EXIT WHEN octet_length(payload) < 7900;
      IF take_count = 1 THEN
        RAISE WARNING
          'emit_realtime_entity_change: one-recipient payload exceeded byte budget for kind %',
          p_entity;
        payload := NULL;
        EXIT;
      END IF;
      take_count := GREATEST(1, take_count / 2);
    END LOOP;

    IF payload IS NOT NULL THEN
      BEGIN
        PERFORM pg_notify('entity_changes', payload);
      EXCEPTION
        WHEN OTHERS THEN
          RAISE WARNING
            'emit_realtime_entity_change: pg_notify failed for kind % recipients %: %',
            p_entity, take_count, SQLERRM;
      END;
    END IF;
    recipient_index := recipient_index + take_count;
  END LOOP;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'emit_realtime_entity_change: envelope failed for kind %: %',
      COALESCE(p_entity, '<null>'), SQLERRM;
END;
$$
''',

  r'''
CREATE FUNCTION public.emit_realtime_entity_change_strict(p_entity text, p_id text, p_event text, p_user_ids text[], p_extra jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  normalized_user_ids text[];
  actor_user_id text;
  recipient_index integer := 1;
  recipient_count integer;
  take_count integer;
  recipient_chunk text[];
  payload text;
BEGIN
  IF p_entity IS NULL OR p_entity = ''
     OR p_id IS NULL OR p_id = ''
     OR p_event NOT IN ('insert', 'update', 'delete') THEN
    RAISE EXCEPTION
      'emit_realtime_entity_change_strict: invalid envelope for kind %',
      COALESCE(p_entity, '<null>');
  END IF;

  SELECT COALESCE(array_agg(DISTINCT user_id ORDER BY user_id), ARRAY[]::text[])
  INTO normalized_user_ids
  FROM unnest(COALESCE(p_user_ids, ARRAY[]::text[])) AS user_id
  WHERE user_id IS NOT NULL AND user_id <> '';

  IF cardinality(normalized_user_ids) = 0 THEN
    RAISE EXCEPTION
      'emit_realtime_entity_change_strict: empty recipients for kind %',
      p_entity;
  END IF;

  actor_user_id := NULLIF(
    current_setting('tentura.mutating_user_id', true),
    ''
  );
  recipient_count := cardinality(normalized_user_ids);

  WHILE recipient_index <= recipient_count LOOP
    take_count := LEAST(100, recipient_count - recipient_index + 1);

    LOOP
      recipient_chunk := normalized_user_ids[
        recipient_index:recipient_index + take_count - 1
      ];
      payload := jsonb_strip_nulls(
        jsonb_build_object(
          'event', p_event,
          'entity', p_entity,
          'id', p_id,
          'user_ids', to_jsonb(recipient_chunk),
          'actor_user_id', actor_user_id
        ) || COALESCE(p_extra, '{}'::jsonb)
      )::text;

      EXIT WHEN octet_length(payload) < 7900;
      IF take_count = 1 THEN
        RAISE EXCEPTION
          'emit_realtime_entity_change_strict: payload exceeded byte budget for kind %',
          p_entity;
      END IF;
      take_count := GREATEST(1, take_count / 2);
    END LOOP;

    PERFORM pg_notify('entity_changes', payload);
    recipient_index := recipient_index + take_count;
  END LOOP;
END;
$$
''',

  r'''
CREATE VIEW public.graph_score AS
 SELECT ''::text AS src,
    ''::text AS dst,
    (0)::double precision AS src_score,
    (0)::double precision AS dst_score,
    0 AS src_total_neighbor_count,
    0 AS dst_total_neighbor_count
  WHERE false
''',

  r'''
CREATE FUNCTION public.graph(focus text, context text, positive_only boolean, hasura_session json) RETURNS SETOF public.graph_score
    LANGUAGE sql STABLE
    AS $$
SELECT
  g.src,
  g.dst,
  g.score_cluster_of_ego AS src_score,
  g.score_cluster_of_dst AS dst_score,
  public.user_trust_edge_degree(g.src, positive_only) AS src_total_neighbor_count,
  public.user_trust_edge_degree(g.dst, positive_only) AS dst_total_neighbor_count
FROM
  mr_graph(
    hasura_session ->> 'x-hasura-user-id',
    focus,
    context,
    positive_only,
    0,
    100
  ) AS g
WHERE NOT public.block_hides(hasura_session ->> 'x-hasura-user-id', g.src)
  AND NOT public.block_hides(hasura_session ->> 'x-hasura-user-id', g.dst);
$$
''',

  r'''
CREATE FUNCTION public.graph_edges_between(node_ids text[], positive_only boolean, hasura_session json) RETURNS SETOF public.graph_score
    LANGUAGE sql STABLE
    AS $$
SELECT
  e.subject AS src,
  e.object AS dst,
  (0)::double precision AS src_score,
  e.prev_sent_weight AS dst_score,
  public.user_trust_edge_degree(e.subject, positive_only) AS src_total_neighbor_count,
  public.user_trust_edge_degree(e.object, positive_only) AS dst_total_neighbor_count
FROM public.user_trust_edge e
WHERE e.subject = ANY(node_ids)
  AND e.object = ANY(node_ids)
  AND (positive_only = false OR e.prev_sent_weight > 0)
  AND NOT public.block_hides(hasura_session ->> 'x-hasura-user-id', e.subject)
  AND NOT public.block_hides(hasura_session ->> 'x-hasura-user-id', e.object);
$$
''',

  r'''
CREATE FUNCTION public.inbox_item_apply_tombstone_after_withdraw(p_user_id text, p_beacon_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM set_config('tentura.allow_inbox_tombstone_transition', '1', true);
  UPDATE public.inbox_item ii
  SET
    status = CASE (SELECT b.status FROM public.beacon b WHERE b.id = p_beacon_id)
      WHEN 2 THEN 4 ELSE 3 END,
    before_response_terminal_at = coalesce(
      ii.before_response_terminal_at,
      now()
    )
  WHERE ii.user_id = p_user_id
    AND ii.beacon_id = p_beacon_id
    AND EXISTS (
      SELECT 1
      FROM public.beacon b
      WHERE b.id = p_beacon_id AND b.status NOT IN (0, 7, 8)
    );
END;
$$
''',

  r'''
CREATE FUNCTION public.inbox_item_guard_tombstone() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  allow text;
BEGIN
  allow := current_setting('tentura.allow_inbox_tombstone_transition', true);
  IF TG_OP = 'INSERT' AND NEW.status IN (3, 4) THEN
    IF allow IS DISTINCT FROM '1' THEN
      RAISE EXCEPTION 'inbox_item cannot insert tombstone status without beacon trigger';
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD.status IN (3, 4) THEN
      IF NEW.status IS DISTINCT FROM OLD.status
         OR NEW.rejection_message IS DISTINCT FROM OLD.rejection_message THEN
        RAISE EXCEPTION 'inbox_item tombstone rows cannot change status or rejection_message';
      END IF;
    END IF;
    -- m0183: `tombstone_dismissed_at` is no longer restricted to statuses
    -- 3 and 4. Every outcome kind carries its own dismiss control, so every
    -- outcome kind must be dismissable and un-dismissable (U09c undo).
    IF NEW.status IN (3, 4) AND OLD.status NOT IN (3, 4) THEN
      IF allow IS DISTINCT FROM '1' THEN
        RAISE EXCEPTION 'inbox_item cannot transition to tombstone status without beacon trigger';
      END IF;
    END IF;
    IF OLD.status IN (3, 4) AND NEW.status IN (3, 4)
       AND OLD.status IS DISTINCT FROM NEW.status THEN
      IF allow IS DISTINCT FROM '1' THEN
        RAISE EXCEPTION 'inbox_item tombstone status upgrade requires beacon trigger';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$
''',

  r'''
CREATE FUNCTION public.inbox_item_guard_unanswered_dismissal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  answered boolean;
BEGIN
  IF NEW.tombstone_dismissed_at IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.tombstone_dismissed_at IS NOT DISTINCT FROM OLD.tombstone_dismissed_at THEN
    RETURN NEW;
  END IF;
  IF NEW.status <> 0 THEN
    RETURN NEW;
  END IF;

  -- status 0 is `helping` exactly when the Request is in the viewer's
  -- responsibility scope. This mirrors the `scope` CTE shared by
  -- `AttentionDismissibleSql.prelude` and `attention_repository.dart`: the
  -- base beacons (authored, or an open help offer) plus any Request carrying
  -- a live, unsettled obligation receipt for this viewer.
  SELECT EXISTS (
    SELECT 1
    FROM public.responsibility_scope_base_beacons(NEW.user_id) base
    WHERE base.beacon_id = NEW.beacon_id
  ) OR EXISTS (
    SELECT 1
    FROM public.visible_attention_receipts(NEW.user_id) authorized
    JOIN public.notification_outbox outbox
      ON outbox.id = authorized.receipt_id
    WHERE outbox.beacon_id = NEW.beacon_id
      AND outbox.requires_action
      AND outbox.settlement_kind IS NULL
  ) INTO answered;

  IF NOT answered THEN
    RAISE EXCEPTION
      'inbox_item unanswered forward cannot be dismissed (owner decision A: a row awaiting a decision never carries its own x)';
  END IF;

  RETURN NEW;
END;
$$
''',

  r'''
CREATE TABLE public.inbox_item (
    user_id text NOT NULL,
    beacon_id text NOT NULL,
    context text,
    forward_count integer DEFAULT 0 NOT NULL,
    latest_forward_at timestamp with time zone DEFAULT now() NOT NULL,
    latest_note_preview text DEFAULT ''::text NOT NULL,
    status smallint DEFAULT 0 NOT NULL,
    rejection_message text DEFAULT ''::text NOT NULL,
    before_response_terminal_at timestamp with time zone,
    tombstone_dismissed_at timestamp with time zone,
    CONSTRAINT ii_rejection_message_length CHECK ((char_length(rejection_message) <= 200))
)
''',

  r'''
COMMENT ON COLUMN public.inbox_item.status IS '0=needs_me,1=watching,2=rejected,3=closed_before_response,4=deleted_before_response'

''',

  r'''
COMMENT ON COLUMN public.inbox_item.before_response_terminal_at IS 'When the row first entered a before-response terminal status (3 or 4)'

''',

  r'''
COMMENT ON COLUMN public.inbox_item.tombstone_dismissed_at IS 'When set, the viewer dismissed this outcome row; it stops asking for attention and does not change stance. Valid for every status since m0183 — helping, watching and notInterested rows carry a dismiss control too. Distinct axis from notification_outbox.cleared_at, which is the receipt axis.'

''',

  r'''
CREATE FUNCTION public.inbox_item_inbox_provenance_data(inbox_row public.inbox_item, hasura_session json) RETURNS text
    LANGUAGE plpgsql STABLE
