''',

  r'''
CREATE FUNCTION public.inbox_item_maintain_attention_request_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  decision_bump int := 0;
  outcome_bump int := 0;
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.attention_request_state
      (account_id, beacon_id, first_entry_at, outcome_generation, decision_revision)
    VALUES (
      NEW.user_id,
      NEW.beacon_id,
      LEAST(now(), COALESCE(NEW.latest_forward_at, now())),
      0,
      0
    )
    ON CONFLICT (account_id, beacon_id) DO NOTHING;
    RETURN NULL;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status
     OR NEW.rejection_message IS DISTINCT FROM OLD.rejection_message THEN
    decision_bump := 1;
  END IF;

  outcome_bump := decision_bump;
  IF NEW.latest_forward_at IS DISTINCT FROM OLD.latest_forward_at
     OR NEW.before_response_terminal_at IS DISTINCT FROM OLD.before_response_terminal_at THEN
    outcome_bump := 1;
  END IF;

  IF decision_bump = 0 AND outcome_bump = 0 THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.attention_request_state
    (account_id, beacon_id, first_entry_at, outcome_generation, decision_revision)
  VALUES (
    NEW.user_id,
    NEW.beacon_id,
    LEAST(now(), COALESCE(NEW.latest_forward_at, now())),
    outcome_bump,
    decision_bump
  )
  ON CONFLICT (account_id, beacon_id) DO UPDATE SET
    outcome_generation =
      public.attention_request_state.outcome_generation + outcome_bump,
    decision_revision =
      public.attention_request_state.decision_revision + decision_bump;

  RETURN NULL;
END;
$$
''',

  r'''
CREATE FUNCTION public.inbox_item_on_forward_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO public.inbox_item (user_id, beacon_id, context, forward_count, latest_forward_at, latest_note_preview)
  VALUES (NEW.recipient_id, NEW.beacon_id, NEW.context, 1, NEW.created_at,
    CASE WHEN char_length(NEW.note) > 200 THEN substring(NEW.note FROM 1 FOR 200) ELSE NEW.note END)
  ON CONFLICT (user_id, beacon_id) DO UPDATE SET
    forward_count = inbox_item.forward_count + 1,
    latest_forward_at = GREATEST(inbox_item.latest_forward_at, NEW.created_at),
    latest_note_preview = CASE
      WHEN NEW.created_at > inbox_item.latest_forward_at
        THEN CASE WHEN char_length(NEW.note) > 200 THEN substring(NEW.note FROM 1 FOR 200) ELSE NEW.note END
      ELSE inbox_item.latest_note_preview
    END,
    context = COALESCE(NEW.context, inbox_item.context);
  RETURN NEW;
END;
$$
''',

  r'''
CREATE FUNCTION public.inbox_item_on_rejection_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 2 THEN
    UPDATE public.beacon_forward_edge
    SET recipient_rejected = true,
        recipient_rejection_message = NEW.rejection_message
    WHERE recipient_id = NEW.user_id AND beacon_id = NEW.beacon_id;
  ELSIF OLD.status = 2 AND NEW.status <> 2 THEN
    UPDATE public.beacon_forward_edge
    SET recipient_rejected = false,
        recipient_rejection_message = ''::text
    WHERE recipient_id = NEW.user_id AND beacon_id = NEW.beacon_id;
  END IF;
  RETURN NEW;
END;
$$
''',

  r'''
CREATE FUNCTION public.invite_genealogy_anonymize_deleted_user() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE public.invite_genealogy
  SET
    descendant_user_id = NULL,
    descendant_deleted_at = COALESCE(descendant_deleted_at, now())
  WHERE descendant_user_id = OLD.id;

  UPDATE public.invite_genealogy
  SET
    ancestor_user_id = NULL,
    ancestor_deleted_at = COALESCE(ancestor_deleted_at, now())
  WHERE ancestor_user_id = OLD.id;

  RETURN OLD;
END;
$$
''',

  r'''
CREATE FUNCTION public.meritrank_init() RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  _meritrank_new_edges_enabled constant boolean := false;
  _src text[];
  _dst text[];
  _weight float8[];
  _magnitude bigint[];
  _context text[];
  _total integer := 0;
  _edge_count integer;
BEGIN
  WITH all_edges AS (
    SELECT subject AS src, object AS dst, prev_sent_weight AS weight, 0::bigint AS magnitude, ''::text AS context FROM user_trust_edge
    UNION ALL
    SELECT pv.id, p.id, 1.0::float8, 0::bigint, ''::text FROM polling p JOIN polling_variant pv ON p.id = pv.polling_id WHERE p.enabled = true
    UNION ALL
    SELECT pa.author_id, pa.polling_variant_id, 1.0::float8, 0::bigint, ''::text FROM polling_act pa JOIN polling p ON p.id = pa.polling_id WHERE p.enabled = true
  ),
  agg AS (
    SELECT
      coalesce(array_agg(src), ARRAY[]::text[]) AS src_arr,
      coalesce(array_agg(dst), ARRAY[]::text[]) AS dst_arr,
      coalesce(array_agg(weight), ARRAY[]::float8[]) AS weight_arr,
      coalesce(array_agg(magnitude), ARRAY[]::bigint[]) AS magnitude_arr,
      coalesce(array_agg(context), ARRAY[]::text[]) AS context_arr,
      count(*)::int AS cnt
    FROM all_edges
  )
  SELECT src_arr, dst_arr, weight_arr, magnitude_arr, context_arr, cnt
  INTO _src, _dst, _weight, _magnitude, _context, _edge_count
  FROM agg;

  _total := _total + _edge_count;
  PERFORM mr_bulk_load_edges(_src, _dst, _weight, _magnitude, _context, 120000::bigint);

  IF _meritrank_new_edges_enabled THEN
    SELECT _total + count(*)::int INTO _total FROM (SELECT mr_set_new_edges_filter(user_id, filter) FROM user_updates) AS _;
  END IF;

  RETURN _total;
END;
$$
''',

  r'''
