  r'''
CREATE FUNCTION public.nested_requests_apply_legacy_cleanup() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Maintenance cleanup, not a normal user write: this whole function only
  -- clears stale references on rows that survive cleanup (never posts new
  -- content), so it must bypass the lifecycle/general-only write guards for
  -- beacons that have already reached a terminal or non-General state.
  SET LOCAL tentura.discussion_internal_fixture = 'allow_non_general';

  -- §5.3 step 2 — snapshot doomed sets (transaction-local).
  CREATE TEMP TABLE m0158_doomed_items ON COMMIT DROP AS
    SELECT id
    FROM public.coordination_item
    WHERE kind IN (2, 3, 5);

  CREATE TEMP TABLE m0158_doomed_messages ON COMMIT DROP AS
    SELECT id
    FROM public.beacon_room_message
    WHERE thread_item_id IS NOT NULL;

  CREATE TEMP TABLE m0158_doomed_attachment_images ON COMMIT DROP AS
    SELECT DISTINCT a.image_id, i.author_id
    FROM public.beacon_room_message_attachment a
    INNER JOIN public.image i ON i.id = a.image_id
    INNER JOIN m0158_doomed_messages dm ON dm.id = a.message_id
    WHERE a.image_id IS NOT NULL;

  CREATE TEMP TABLE m0158_affected_receipts ON COMMIT DROP AS
    SELECT n.id, n.occurrence_id
    FROM public.notification_outbox n
    WHERE n.coordination_item_id IN (SELECT id FROM m0158_doomed_items)
       OR n.target_entity_id IN (SELECT id FROM m0158_doomed_messages)
       OR COALESCE(n.presentation_payload ->> 'coordinationItemId', '')
            IN (SELECT id FROM m0158_doomed_items)
       OR COALESCE(n.presentation_payload ->> 'messageId', '')
            IN (SELECT id FROM m0158_doomed_messages);

  CREATE TEMP TABLE m0158_affected_occurrences ON COMMIT DROP AS
    SELECT DISTINCT occ.id
    FROM public.attention_occurrence occ
    WHERE occ.id IN (
      SELECT occurrence_id FROM m0158_affected_receipts WHERE occurrence_id IS NOT NULL
    );

  -- §5.3 step 3 — preserve supported rows; null dangling provenance only.
  UPDATE public.beacon_fact_card
  SET source_message_id = NULL
  WHERE source_message_id IN (SELECT id FROM m0158_doomed_messages);

  UPDATE public.beacon_promotions
  SET source_message_id = NULL
  WHERE source_message_id IN (SELECT id FROM m0158_doomed_messages);

  UPDATE public.coordination_item ci
  SET target_item_id = NULL
  WHERE ci.target_item_id IN (SELECT id FROM m0158_doomed_items);

  UPDATE public.coordination_item ci
  SET linked_message_id = NULL
  WHERE ci.linked_message_id IN (SELECT id FROM m0158_doomed_messages);

  UPDATE public.coordination_item ci
  SET target_message_id = NULL
  WHERE ci.target_message_id IN (SELECT id FROM m0158_doomed_messages);

  UPDATE public.beacon_room_message m
  SET reply_to_message_id = NULL
  WHERE m.reply_to_message_id IN (SELECT id FROM m0158_doomed_messages)
    AND m.id NOT IN (SELECT id FROM m0158_doomed_messages);

  -- §5.3 step 4 — remove obsolete General anchors; clear retired links on survivors.
  -- Anchor rows are pure system notifies (empty body, e.g. from
  -- CoordinationItemRepository._emitCreatedRoomNotify's standalone/notify
  -- branches); a non-empty body means a real user message merely carries a
  -- footer/link to the retired item, and must survive with only the link
  -- cleared below.
  DELETE FROM public.beacon_room_message m
  WHERE m.thread_item_id IS NULL
    AND m.linked_item_id IN (SELECT id FROM m0158_doomed_items)
    AND m.linked_event_kind IS NOT NULL
    AND m.body = '';

  UPDATE public.beacon_room_message m
  SET
    linked_item_id = NULL,
    linked_event_kind = NULL,
    system_payload = NULL
  WHERE m.thread_item_id IS NULL
    AND m.linked_item_id IN (SELECT id FROM m0158_doomed_items);

  UPDATE public.beacon_room_state rs
  SET open_blocker_id = NULL
  WHERE rs.open_blocker_id IN (SELECT id FROM m0158_doomed_items);

  -- §5.3 step 5 — attention / destinations in verified FK order.
  DELETE FROM public.beacon_activity_event e
  WHERE e.coordination_item_id IN (SELECT id FROM m0158_doomed_items)
     OR e.source_message_id IN (SELECT id FROM m0158_doomed_messages);

  DELETE FROM public.attention_channel_delivery d
  WHERE d.receipt_id IN (SELECT id FROM m0158_affected_receipts)
     OR d.occurrence_id IN (SELECT id FROM m0158_affected_occurrences);

  DELETE FROM public.notification_outbox n
  WHERE n.id IN (SELECT id FROM m0158_affected_receipts);

  DELETE FROM public.attention_occurrence_recipient r
  WHERE r.occurrence_id IN (SELECT id FROM m0158_affected_occurrences);

  DELETE FROM public.attention_occurrence o
  WHERE o.id IN (SELECT id FROM m0158_affected_occurrences);

  -- §5.3 step 6 — room-owned polls, then semantic messages, then retired items.
  CREATE TEMP TABLE m0158_doomed_polls ON COMMIT DROP AS
    SELECT DISTINCT m.linked_polling_id AS id
    FROM public.beacon_room_message m
    WHERE m.id IN (SELECT id FROM m0158_doomed_messages)
      AND m.linked_polling_id IS NOT NULL;

  DELETE FROM public.polling_act pa
  WHERE pa.polling_id IN (SELECT id FROM m0158_doomed_polls);

  DELETE FROM public.polling_variant pv
  WHERE pv.polling_id IN (SELECT id FROM m0158_doomed_polls);

  DELETE FROM public.polling p
  WHERE p.id IN (SELECT id FROM m0158_doomed_polls);

  DELETE FROM public.beacon_room_message m
  WHERE m.id IN (SELECT id FROM m0158_doomed_messages);

  DELETE FROM public.beacon_room_seen s
  WHERE s.thread_item_id IS NOT NULL;

  DELETE FROM public.coordination_item ci
  WHERE ci.id IN (SELECT id FROM m0158_doomed_items);

  -- §5.3 step 7 — queue then drop unreferenced attachment blobs (DB only).
  INSERT INTO public.image_object_gc (image_id, author_id)
  SELECT dai.image_id, dai.author_id
  FROM m0158_doomed_attachment_images dai
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.beacon_room_message_attachment att
    WHERE att.image_id = dai.image_id
  )
  AND NOT EXISTS (
    SELECT 1 FROM public.beacon_image bi WHERE bi.image_id = dai.image_id
  )
  AND NOT EXISTS (
    SELECT 1 FROM public.beacon b
    WHERE b.cover_image_id = dai.image_id
       OR b.cover_thumb_image_id = dai.image_id
  )
  AND NOT EXISTS (
    SELECT 1 FROM public.beacon_image_stage s WHERE s.image_id = dai.image_id
  )
  ON CONFLICT (image_id) DO NOTHING;

  DELETE FROM public.image i
  USING m0158_doomed_attachment_images dai
  WHERE i.id = dai.image_id
    AND EXISTS (
      SELECT 1 FROM public.image_object_gc gc WHERE gc.image_id = dai.image_id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.beacon_room_message_attachment att
      WHERE att.image_id = dai.image_id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.beacon_image bi WHERE bi.image_id = dai.image_id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.beacon b
      WHERE b.cover_image_id = dai.image_id
         OR b.cover_thumb_image_id = dai.image_id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.beacon_image_stage s WHERE s.image_id = dai.image_id
    );

  -- §5.3 step 8 — rebuild only affected preview pointers from remaining data.
  UPDATE public.beacon_room_state rs
  SET last_room_meaningful_change = NULL
  WHERE rs.last_room_meaningful_change IN (SELECT id FROM m0158_doomed_messages);

  UPDATE public.beacon_room_message m
  SET linked_polling_id = NULL
  WHERE m.linked_polling_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.polling p WHERE p.id = m.linked_polling_id
    );
END;
$$
''',

  r'''
CREATE FUNCTION public.notify_beacon_hierarchy_admission_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  beacon_id text;
  parent_id text;
  affected_user_id text;
  extra_users text[] := ARRAY[]::text[];
BEGIN
  IF TG_TABLE_NAME = 'beacon_participant' THEN
    beacon_id := COALESCE(NEW.beacon_id, OLD.beacon_id);
    affected_user_id := COALESCE(NEW.user_id, OLD.user_id);
  ELSIF TG_TABLE_NAME = 'beacon_steward' THEN
    beacon_id := COALESCE(NEW.beacon_id, OLD.beacon_id);
    affected_user_id := COALESCE(NEW.user_id, OLD.user_id);
  ELSIF TG_TABLE_NAME = 'user_block' THEN
    affected_user_id := COALESCE(NEW.blocked_id, OLD.blocked_id);
    extra_users := ARRAY[
      COALESCE(NEW.blocker_id, OLD.blocker_id),
      COALESCE(NEW.blocked_id, OLD.blocked_id)
    ];
    FOR beacon_id IN
      SELECT DISTINCT q.beacon_id
      FROM (
        SELECT b.id AS beacon_id
        FROM public.beacon b
        WHERE b.user_id IN (
          COALESCE(NEW.blocker_id, OLD.blocker_id),
          COALESCE(NEW.blocked_id, OLD.blocked_id)
        )
        UNION
        SELECT b.id
        FROM public.beacon b
        JOIN public.beacon parent ON parent.id = b.parent_beacon_id
        WHERE parent.user_id IN (
          COALESCE(NEW.blocker_id, OLD.blocker_id),
          COALESCE(NEW.blocked_id, OLD.blocked_id)
        )
          AND b.published_at IS NOT NULL
        UNION
        SELECT parent.id
        FROM public.beacon b
        JOIN public.beacon parent ON parent.id = b.parent_beacon_id
        WHERE b.user_id IN (
          COALESCE(NEW.blocker_id, OLD.blocker_id),
          COALESCE(NEW.blocked_id, OLD.blocked_id)
        )
          AND b.published_at IS NOT NULL
      ) q
      LIMIT 50
    LOOP
      PERFORM public.realtime_beacon_hierarchy_emit(
        beacon_id,
        lower(TG_OP),
        extra_users
      );
    END LOOP;
    RETURN NULL;
  ELSE
    RETURN NULL;
  END IF;

  IF affected_user_id IS NOT NULL AND affected_user_id <> '' THEN
    extra_users := extra_users || ARRAY[affected_user_id];
  END IF;

  PERFORM public.realtime_beacon_hierarchy_emit(
    beacon_id,
    lower(TG_OP),
    extra_users
  );

  SELECT b.parent_beacon_id
  INTO parent_id
  FROM public.beacon b
  WHERE b.id = beacon_id;

  IF parent_id IS NOT NULL AND parent_id <> '' THEN
    PERFORM public.realtime_beacon_hierarchy_emit(
      parent_id,
      lower(TG_OP),
      extra_users
    );
  END IF;

  RETURN NULL;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING
      'notify_beacon_hierarchy_admission_change failed without aborting write: %',
      SQLERRM;
    RETURN NULL;
END;
$$
''',

  r'''
CREATE FUNCTION public.notify_beacon_hierarchy_beacon_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  child_row record;
  parent_id text;
  projected_changed boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.published_at IS NOT NULL AND NEW.parent_beacon_id IS NOT NULL THEN
      PERFORM public.realtime_beacon_hierarchy_emit(NEW.parent_beacon_id, 'insert');
    END IF;
    RETURN NULL;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.published_at IS NOT NULL AND OLD.parent_beacon_id IS NOT NULL THEN
      PERFORM public.realtime_beacon_hierarchy_emit(OLD.parent_beacon_id, 'delete');
      PERFORM public.realtime_beacon_hierarchy_emit(OLD.id, 'delete');
    ELSIF OLD.published_at IS NOT NULL THEN
      PERFORM public.realtime_beacon_hierarchy_emit(OLD.id, 'delete');
      FOR child_row IN
        SELECT b.id
        FROM public.beacon b
        WHERE b.parent_beacon_id = OLD.id
          AND b.published_at IS NOT NULL
      LOOP
        PERFORM public.realtime_beacon_hierarchy_emit(child_row.id, 'delete');
      END LOOP;
    END IF;
    RETURN NULL;
  END IF;

  -- Draft edits stay on the ordinary beacon channel for the owner only.
  IF NEW.published_at IS NULL THEN
    RETURN NULL;
  END IF;

  IF OLD.published_at IS NULL AND NEW.published_at IS NOT NULL
     AND NEW.parent_beacon_id IS NOT NULL THEN
    PERFORM public.realtime_beacon_hierarchy_emit(NEW.parent_beacon_id, 'update');
    RETURN NULL;
  END IF;

  parent_id := NEW.parent_beacon_id;

  projected_changed :=
    OLD.title IS DISTINCT FROM NEW.title
    OR OLD.status IS DISTINCT FROM NEW.status
    OR OLD.user_id IS DISTINCT FROM NEW.user_id
    OR OLD.description IS DISTINCT FROM NEW.description
    OR OLD.cover_source IS DISTINCT FROM NEW.cover_source
    OR OLD.cover_image_id IS DISTINCT FROM NEW.cover_image_id
    OR OLD.cover_thumb_image_id IS DISTINCT FROM NEW.cover_thumb_image_id
    OR OLD.primary_need_slug IS DISTINCT FROM NEW.primary_need_slug
    OR OLD.needs IS DISTINCT FROM NEW.needs
    OR OLD.status_changed_at IS DISTINCT FROM NEW.status_changed_at;

  IF projected_changed THEN
    -- Chat preview listens on the child aggregate id; Now list on the parent.
    PERFORM public.realtime_beacon_hierarchy_emit(NEW.id, 'update');
    IF parent_id IS NOT NULL THEN
      PERFORM public.realtime_beacon_hierarchy_emit(parent_id, 'update');
    END IF;
  END IF;

  IF OLD.status IS DISTINCT FROM NEW.status AND NEW.status IN (2, 3) THEN
    FOR child_row IN
      SELECT b.id
      FROM public.beacon b
      WHERE b.parent_beacon_id = NEW.id
        AND b.published_at IS NOT NULL
    LOOP
      PERFORM public.realtime_beacon_hierarchy_emit(child_row.id, 'update');
    END LOOP;
  END IF;

  RETURN NULL;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING
      'notify_beacon_hierarchy_beacon_change failed without aborting write: %',
      SQLERRM;
    RETURN NULL;
END;
$$
''',

  r'''
CREATE FUNCTION public.notify_beacon_hierarchy_profile_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  beacon_id text;
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RETURN NULL;
  END IF;

  IF NOT (
    OLD.display_name IS DISTINCT FROM NEW.display_name
    OR OLD.image_id IS DISTINCT FROM NEW.image_id
  ) THEN
    RETURN NULL;
  END IF;

  -- Owned published beacons (+ their parents) and admitted-helper memberships.
  FOR beacon_id IN
    SELECT DISTINCT q.beacon_id
    FROM (
      SELECT b.id AS beacon_id
      FROM public.beacon b
      WHERE b.user_id = NEW.id
        AND b.published_at IS NOT NULL
      UNION
      SELECT b.parent_beacon_id
      FROM public.beacon b
      WHERE b.user_id = NEW.id
        AND b.published_at IS NOT NULL
        AND b.parent_beacon_id IS NOT NULL
      UNION
      SELECT bah.beacon_id
      FROM public.beacon_admitted_helper bah
      WHERE bah.user_id = NEW.id
      UNION
      SELECT b.parent_beacon_id
      FROM public.beacon_admitted_helper bah
      JOIN public.beacon b ON b.id = bah.beacon_id
      WHERE bah.user_id = NEW.id
        AND b.parent_beacon_id IS NOT NULL
    ) q
    LIMIT 50
  LOOP
    PERFORM public.realtime_beacon_hierarchy_emit(beacon_id, 'update');
  END LOOP;

  RETURN NULL;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING
      'notify_beacon_hierarchy_profile_change failed without aborting write: %',
      SQLERRM;
    RETURN NULL;
END;
$$
''',

  r'''
