  r'''
CREATE FUNCTION public.notify_constellation_anchor_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  _viewer_id text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    _viewer_id := OLD.viewer_id;
    IF NOT EXISTS (
      SELECT 1 FROM public.constellation_anchor_cursor c
      WHERE c.viewer_id = _viewer_id
    ) THEN
      RETURN OLD;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public."user" u WHERE u.id = _viewer_id
    ) THEN
      RETURN OLD;
    END IF;
  ELSE
    _viewer_id := NEW.viewer_id;
  END IF;

  PERFORM public.emit_realtime_entity_change_strict(
    'constellation_anchor',
    _viewer_id,
    lower(TG_OP),
    ARRAY[_viewer_id]
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$
''',

  r'''
