  r'''
CREATE FUNCTION public.notify_notification_outbox_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  affected_account_id text;
BEGIN
  FOR affected_account_id IN
    WITH changed_rows AS (
      SELECT old_row.account_id AS old_account_id,
             new_row.account_id AS new_account_id
      FROM old_rows old_row
      FULL OUTER JOIN new_rows new_row ON new_row.id = old_row.id
      WHERE ROW(
        old_row.id,
        old_row.account_id,
        old_row.category,
        old_row.kind,
        old_row.priority,
        old_row.title,
        old_row.body,
        old_row.action_url,
        old_row.created_at,
        old_row.read_at,
        old_row.collapsed_count,
        old_row.beacon_id,
        old_row.coordination_item_id,
        old_row.actor_user_id,
        old_row.seen_at,
        old_row.settlement_kind,
        old_row.settled_at,
        old_row.settled_by_user_id,
        old_row.settled_by_occurrence_id,
        old_row.cleared_at,
        old_row.clear_reason,
        old_row.cleared_by_operation_id,
        old_row.logical_task_key,
        old_row.lifecycle_generation,
        old_row.source_event_key,
        old_row.destination_kind,
        old_row.target_entity_id,
        old_row.presentation_key,
        old_row.presentation_payload,
        old_row.in_app_preference_class,
        old_row.suppression_class,
        old_row.access_policy
      ) IS DISTINCT FROM ROW(
        new_row.id,
        new_row.account_id,
        new_row.category,
        new_row.kind,
        new_row.priority,
        new_row.title,
        new_row.body,
        new_row.action_url,
        new_row.created_at,
        new_row.read_at,
        new_row.collapsed_count,
        new_row.beacon_id,
        new_row.coordination_item_id,
        new_row.actor_user_id,
        new_row.seen_at,
        new_row.settlement_kind,
        new_row.settled_at,
        new_row.settled_by_user_id,
        new_row.settled_by_occurrence_id,
        new_row.cleared_at,
        new_row.clear_reason,
        new_row.cleared_by_operation_id,
        new_row.logical_task_key,
        new_row.lifecycle_generation,
        new_row.source_event_key,
        new_row.destination_kind,
        new_row.target_entity_id,
        new_row.presentation_key,
        new_row.presentation_payload,
        new_row.in_app_preference_class,
        new_row.suppression_class,
        new_row.access_policy
      )
    ),
    affected_accounts AS (
      SELECT old_account_id AS account_id FROM changed_rows
      UNION
      SELECT new_account_id AS account_id FROM changed_rows
    )
    SELECT account_id
    FROM affected_accounts
    WHERE account_id IS NOT NULL AND account_id <> ''
    ORDER BY account_id
  LOOP
    PERFORM public.emit_realtime_entity_change(
      'notification',
      affected_account_id,
      'update',
      ARRAY[affected_account_id]
    );
  END LOOP;
  RETURN NULL;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING
      'notify_notification_outbox_update failed without aborting write: %',
      SQLERRM;
    RETURN NULL;
END;
$$
''',

  r'''
CREATE FUNCTION public.notify_relationship_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  changed_subject_ids text[];
  subject_chunk text[];
  user_ids text[];
  subject_index integer := 1;
  subject_count integer;
BEGIN
  -- Bulk trust maintenance (full recompute / single-source resync) rewrites
  -- prev_sent_weight for decay bookkeeping without changing any client-visible
  -- relationship. Those paths set this transaction-local flag so the rewrite
  -- does not fan a relationship invalidation out to every recipient.
  IF current_setting('tentura.suppress_relationship_notify', true) = '1' THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT array_agg(DISTINCT id ORDER BY id)
    INTO changed_subject_ids
    FROM (
      SELECT subject AS id FROM new_rows
      UNION
      SELECT object AS id FROM new_rows
    ) changed;
  ELSIF TG_OP = 'DELETE' THEN
    SELECT array_agg(DISTINCT id ORDER BY id)
    INTO changed_subject_ids
    FROM (
      SELECT subject AS id FROM old_rows
      UNION
      SELECT object AS id FROM old_rows
    ) changed;
  ELSE
    SELECT array_agg(DISTINCT id ORDER BY id)
    INTO changed_subject_ids
    FROM (
      SELECT subject AS id FROM new_rows
      UNION
      SELECT object AS id FROM new_rows
      UNION
      SELECT subject AS id FROM old_rows
      UNION
      SELECT object AS id FROM old_rows
    ) changed;
  END IF;

  subject_count := cardinality(COALESCE(changed_subject_ids, ARRAY[]::text[]));
  WHILE subject_index <= subject_count LOOP
    subject_chunk := changed_subject_ids[
      subject_index:LEAST(subject_index + 99, subject_count)
    ];
    user_ids := public.realtime_subject_recipients(subject_chunk);
    PERFORM public.emit_realtime_entity_change(
      'relationship',
      subject_chunk[1],
      lower(TG_OP),
      user_ids
    );
    subject_index := subject_index + cardinality(subject_chunk);
  END LOOP;
  RETURN NULL;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'notify_relationship_change failed without aborting write: %', SQLERRM;
    RETURN NULL;
END;
$$
''',

  r'''
CREATE FUNCTION public.notify_room_message_attachment_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  message_id text;
  beacon_id text;
  author_id text;
  thread_item_id text;
  user_ids text[];
BEGIN
  message_id := COALESCE(NEW.message_id, OLD.message_id);

  SELECT m.beacon_id, m.author_id, m.thread_item_id
  INTO beacon_id, author_id, thread_item_id
  FROM public.beacon_room_message m
  WHERE m.id = message_id;

  IF beacon_id IS NULL THEN
    RETURN NULL;
  END IF;

  user_ids := public.realtime_room_recipients(beacon_id) || ARRAY[author_id];
  IF thread_item_id IS NOT NULL THEN
    user_ids := user_ids || COALESCE(
      (
        SELECT ARRAY[ci.creator_id, ci.target_person_id, ci.accepted_by_id]
        FROM public.coordination_item ci
        WHERE ci.id = thread_item_id
      ),
      ARRAY[]::text[]
    );
  END IF;

  PERFORM public.emit_realtime_entity_change(
    'room_message',
    beacon_id,
    'update',
    user_ids,
    jsonb_build_object('message_id', message_id)
  );
  RETURN NULL;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING
      'notify_room_message_attachment_change failed without aborting write: %',
      SQLERRM;
    RETURN NULL;
END;
$$
''',

