  r'''
CREATE FUNCTION public.person_are_mutually_visible(a_id text, b_id text, ctx text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT CASE
  WHEN nullif(trim(coalesce(a_id, '')), '') IS NULL THEN false
  WHEN nullif(trim(coalesce(b_id, '')), '') IS NULL THEN false
  WHEN a_id = b_id THEN false
  WHEN public.person_reciprocal_explicit_trust(a_id, b_id) THEN true          -- §8.4/1
  WHEN public.person_is_mutually_visible(a_id, b_id, coalesce(ctx, '')) THEN true
  ELSE public.person_is_mutually_visible(b_id, a_id, coalesce(ctx, ''))       -- D14 OR-closure
END;
$$
''',

  r'''
CREATE FUNCTION public.person_are_mutually_visible_cached(a_id text, b_id text, ctx text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
#variable_conflict use_column
DECLARE
  _lo text := LEAST(a_id, b_id);
  _hi text := GREATEST(a_id, b_id);
  _ctx text := coalesce(ctx, '');
  _cur_epoch bigint;
  _cur_trust bigint;
  _row public.person_mutual_visibility_cache;
  _result boolean;
BEGIN
  SELECT epoch INTO _cur_epoch FROM public.mr_publish_epoch WHERE id = true;
  _cur_trust := public.direct_trust_current_version();
  SELECT * INTO _row FROM public.person_mutual_visibility_cache c
    WHERE c.person_lo = _lo AND c.person_hi = _hi AND c.ctx = _ctx
    AND c.mr_epoch = _cur_epoch AND c.trust_version = _cur_trust
    AND c.computed_at > now() - interval '60 seconds';
  IF FOUND THEN
    RETURN _row.is_mutually_visible;
  END IF;
  IF current_setting('transaction_read_only', true) = 'on' THEN
    BEGIN
      _result := public.person_are_mutually_visible(a_id, b_id, _ctx);
    EXCEPTION WHEN OTHERS THEN
      RETURN false;
    END;
    RETURN _result;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext(_lo || ':' || _hi || ':' || _ctx));
  SELECT * INTO _row FROM public.person_mutual_visibility_cache c
    WHERE c.person_lo = _lo AND c.person_hi = _hi AND c.ctx = _ctx
    AND c.mr_epoch = _cur_epoch AND c.trust_version = _cur_trust
    AND c.computed_at > now() - interval '60 seconds';
  IF FOUND THEN
    RETURN _row.is_mutually_visible;
  END IF;
  BEGIN
    _result := public.person_are_mutually_visible(a_id, b_id, _ctx);
  EXCEPTION WHEN OTHERS THEN
    RETURN false;
  END;
  INSERT INTO public.person_mutual_visibility_cache
    (person_lo, person_hi, ctx, is_mutually_visible, mr_epoch, trust_version, computed_at)
  VALUES (_lo, _hi, _ctx, _result, _cur_epoch, _cur_trust, now())
  ON CONFLICT (person_lo, person_hi, ctx) DO UPDATE SET
    is_mutually_visible = EXCLUDED.is_mutually_visible,
    mr_epoch = EXCLUDED.mr_epoch,
    trust_version = EXCLUDED.trust_version,
    computed_at = EXCLUDED.computed_at;
  RETURN _result;
END;
$$
''',

  r'''
CREATE FUNCTION public.person_bond(a_id text, b_id text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT nullif(btrim(coalesce(a_id, '')), '') IS NOT NULL
  AND nullif(btrim(coalesce(b_id, '')), '') IS NOT NULL
  AND a_id <> b_id
  AND NOT public.block_hides(a_id, b_id)
  AND EXISTS (
    SELECT 1
    FROM public.beacon_member ma
    JOIN public.beacon_member mb ON mb.beacon_id = ma.beacon_id
    JOIN public.beacon b ON b.id = ma.beacon_id
    WHERE ma.user_id = a_id
      AND mb.user_id = b_id
      AND b.status IN (0, 5, 7, 8)
  );
$$
''',

  r'''
CREATE FUNCTION public.person_bond_peers(p_viewer_id text) RETURNS TABLE(peer_id text)
    LANGUAGE sql STABLE
    AS $$
SELECT DISTINCT mb.user_id::text
FROM public.beacon_member ma
JOIN public.beacon_member mb ON mb.beacon_id = ma.beacon_id
JOIN public.beacon b ON b.id = ma.beacon_id
WHERE ma.user_id = p_viewer_id
  AND mb.user_id <> p_viewer_id
  AND b.status IN (0, 5, 7, 8)
  AND NOT public.block_hides(p_viewer_id, mb.user_id);
$$
''',

  r'''
CREATE FUNCTION public.person_is_mutually_visible(viewer_id text, peer_id text, ctx text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT coalesce(
  (
    SELECT p.is_mutually_visible
    FROM public.person_visibility_peers(viewer_id, ctx) p
    WHERE p.peer_id = person_is_mutually_visible.peer_id
  ),
  false
);
$$
''',

  r'''
