  r'''
CREATE FUNCTION public.realtime_beacon_hierarchy_emit(p_projection_owner_beacon_id text, p_event text, p_extra_user_ids text[] DEFAULT ARRAY[]::text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  user_ids text[];
BEGIN
  IF p_projection_owner_beacon_id IS NULL OR p_projection_owner_beacon_id = '' THEN
    RETURN;
  END IF;

  user_ids := public.realtime_beacon_hierarchy_recipients(
    p_projection_owner_beacon_id
  ) || COALESCE(p_extra_user_ids, ARRAY[]::text[]);

  PERFORM public.emit_realtime_entity_change(
    'beacon_hierarchy',
    p_projection_owner_beacon_id,
    p_event,
    user_ids
  );
END;
$$
''',

  r'''
CREATE FUNCTION public.realtime_beacon_hierarchy_recipients(p_projection_owner_beacon_id text) RETURNS text[]
    LANGUAGE sql STABLE
    AS $$
WITH owner AS (
  SELECT b.user_id AS owner_id, b.parent_beacon_id
  FROM public.beacon b
  WHERE b.id = p_projection_owner_beacon_id
),
direct_admission AS (
  SELECT q.user_id
  FROM owner o
  CROSS JOIN LATERAL (
    SELECT o.owner_id AS user_id
    WHERE o.owner_id IS NOT NULL AND o.owner_id <> ''
    UNION ALL
    SELECT bs.user_id
    FROM public.beacon_steward bs
    WHERE bs.beacon_id = p_projection_owner_beacon_id
    UNION ALL
    SELECT bp.user_id
    FROM public.beacon_participant bp
    WHERE bp.beacon_id = p_projection_owner_beacon_id
      AND (bp.role = 1 OR bp.room_access = 3)
  ) q
  WHERE NOT public.block_hides(o.owner_id, q.user_id)
),
parent_linked AS (
  SELECT q.user_id
  FROM owner o
  JOIN public.beacon parent ON parent.id = o.parent_beacon_id
  CROSS JOIN LATERAL (
    SELECT parent.user_id AS user_id
    WHERE parent.user_id IS NOT NULL AND parent.user_id <> ''
    UNION ALL
    SELECT bs.user_id
    FROM public.beacon_steward bs
    WHERE bs.beacon_id = parent.id
    UNION ALL
    SELECT bp.user_id
    FROM public.beacon_participant bp
    WHERE bp.beacon_id = parent.id
      AND (bp.role = 1 OR bp.room_access = 3)
  ) q
  WHERE o.parent_beacon_id IS NOT NULL
    AND parent.status NOT IN (2, 3)
    AND parent.published_at IS NOT NULL
    AND NOT public.block_hides(parent.user_id, q.user_id)
    AND NOT public.block_hides(o.owner_id, q.user_id)
)
SELECT COALESCE(
  ARRAY(
    SELECT DISTINCT user_id
    FROM (
      SELECT user_id FROM direct_admission
      UNION ALL
      SELECT user_id FROM parent_linked
    ) recipients
    WHERE user_id IS NOT NULL AND user_id <> ''
    ORDER BY user_id
    LIMIT 2000
  ),
  ARRAY[]::text[]
);
$$
''',

  r'''
CREATE FUNCTION public.realtime_beacon_recipients(p_beacon_id text) RETURNS text[]
    LANGUAGE sql STABLE
    AS $$
SELECT COALESCE(array_agg(DISTINCT q.user_id ORDER BY q.user_id), ARRAY[]::text[])
FROM (
  SELECT b.user_id
  FROM public.beacon b
  WHERE b.id = p_beacon_id
  UNION ALL
  SELECT bp.user_id
  FROM public.beacon_participant bp
  WHERE bp.beacon_id = p_beacon_id
  UNION ALL
  SELECT ho.user_id
  FROM public.beacon_help_offer ho
  WHERE ho.beacon_id = p_beacon_id AND ho.status = 0
  UNION ALL
  SELECT fe.sender_id
  FROM public.beacon_forward_edge fe
  WHERE fe.beacon_id = p_beacon_id AND fe.cancelled_at IS NULL
  UNION ALL
  SELECT fe.recipient_id
  FROM public.beacon_forward_edge fe
  WHERE fe.beacon_id = p_beacon_id AND fe.cancelled_at IS NULL
) q
WHERE q.user_id IS NOT NULL AND q.user_id <> '';
$$
''',

  r'''
CREATE FUNCTION public.realtime_room_recipients(p_beacon_id text) RETURNS text[]
    LANGUAGE sql STABLE
    AS $$
SELECT COALESCE(array_agg(DISTINCT q.user_id ORDER BY q.user_id), ARRAY[]::text[])
FROM (
  SELECT b.user_id
  FROM public.beacon b
  WHERE b.id = p_beacon_id
  UNION ALL
  SELECT bp.user_id
  FROM public.beacon_participant bp
  WHERE bp.beacon_id = p_beacon_id AND bp.room_access = 3
) q
WHERE q.user_id IS NOT NULL AND q.user_id <> '';
$$
''',

  r'''
CREATE FUNCTION public.realtime_subject_recipients(p_subject_ids text[]) RETURNS text[]
    LANGUAGE sql STABLE
    AS $$
WITH subjects AS (
  SELECT DISTINCT subject_id
  FROM unnest(COALESCE(p_subject_ids, ARRAY[]::text[])) AS subject_id
  WHERE subject_id IS NOT NULL AND subject_id <> ''
),
mutual_friends AS (
  SELECT DISTINCT CASE
    WHEN vu.subject = s.subject_id THEN vu.object
    ELSE vu.subject
  END AS user_id
  FROM subjects s
  JOIN public.vote_user vu
    ON (vu.subject = s.subject_id OR vu.object = s.subject_id)
   AND vu.amount > 0
  WHERE EXISTS (
    SELECT 1
    FROM public.vote_user reverse_vote
    WHERE reverse_vote.subject = vu.object
      AND reverse_vote.object = vu.subject
      AND reverse_vote.amount > 0
  )
),
shared_beacons AS (
  SELECT b.id AS beacon_id
  FROM subjects s JOIN public.beacon b ON b.user_id = s.subject_id
  UNION
  SELECT bp.beacon_id
  FROM subjects s JOIN public.beacon_participant bp ON bp.user_id = s.subject_id
  UNION
  SELECT ho.beacon_id
  FROM subjects s JOIN public.beacon_help_offer ho ON ho.user_id = s.subject_id
  WHERE ho.status = 0
  UNION
  SELECT fe.beacon_id
  FROM subjects s JOIN public.beacon_forward_edge fe
    ON fe.sender_id = s.subject_id OR fe.recipient_id = s.subject_id
  WHERE fe.cancelled_at IS NULL
),
recipients AS (
  SELECT subject_id AS user_id FROM subjects
  UNION
  SELECT user_id FROM mutual_friends
  UNION
  SELECT unnest(public.realtime_beacon_recipients(beacon_id))
  FROM shared_beacons
)
SELECT COALESCE(
  ARRAY(
    SELECT DISTINCT user_id
    FROM recipients
    WHERE user_id IS NOT NULL AND user_id <> ''
    ORDER BY user_id
    LIMIT 2000
  ),
  ARRAY[]::text[]
);
$$
''',

  r'''
CREATE FUNCTION public.responsibility_scope_base_beacons(p_account_id text) RETURNS TABLE(beacon_id text)
