  r'''
CREATE TABLE public.attention_clear_operation (
    id text NOT NULL,
    account_id text NOT NULL,
    surface text NOT NULL,
    status text NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    undo_deadline timestamp with time zone,
    applied integer DEFAULT 0 NOT NULL,
    skipped integer DEFAULT 0 NOT NULL,
    failed integer DEFAULT 0 NOT NULL,
    CONSTRAINT attention_clear_operation__counters_chk CHECK (((applied >= 0) AND (skipped >= 0) AND (failed >= 0)))
)
''',

  r'''
COMMENT ON TABLE public.attention_clear_operation IS 'Header of one clear/dismiss-all sweep. surface and status are free text until a later unit freezes their vocabularies.'

''',

  r'''
CREATE TABLE public.attention_clear_operation_member (
    operation_id text NOT NULL,
    receipt_id text,
    beacon_id text,
    outcome_generation integer NOT NULL,
    state text NOT NULL,
    outcome_beacon_id text,
    decision_revision integer,
    skip_reason text,
    CONSTRAINT attention_clear_operation_member__decision_revision_chk CHECK (((decision_revision IS NULL) OR (decision_revision >= 0))),
    CONSTRAINT attention_clear_operation_member__generation_chk CHECK ((outcome_generation >= 0)),
    CONSTRAINT attention_clear_operation_member__member_target_chk CHECK ((num_nonnulls(receipt_id, outcome_beacon_id) = 1))
)
''',

  r'''
COMMENT ON TABLE public.attention_clear_operation_member IS 'What a clear/dismiss-all sweep captured. A member is either a receipt (receipt_id, the notification_outbox axis) or an outcome (outcome_beacon_id, the inbox_item.tombstone_dismissed_at axis) — exactly one, by CHECK. Captured once and never extended on retry: the two partial UNIQUE indexes on (operation_id, receipt_id) and (operation_id, outcome_beacon_id) are that guarantee. beacon_id stays an unreferenced snapshot so the audit survives beacon deletion.'

''',

  r'''
COMMENT ON COLUMN public.attention_clear_operation_member.state IS 'pending | applied | skipped | failed. A sweep captures members as pending and decides each one in a later batch, which is what makes it resumable by operation id; U08s single-Request clear decides every member inside the capture transaction and never writes pending.'

''',

  r'''
COMMENT ON COLUMN public.attention_clear_operation_member.outcome_beacon_id IS 'The Request whose outcome row this member dismissed, for members that are outcomes rather than receipts. Exactly one of receipt_id and outcome_beacon_id is set (CHECK). Deliberately not a foreign key, for the same reason beacon_id is not: the operation audit and its counters must survive deletion of the Request, and undo of a member whose Request is gone has nothing to restore and is skipped.'

''',

  r'''
COMMENT ON COLUMN public.attention_clear_operation_member.decision_revision IS 'The viewer decision counter snapshotted at capture, alongside outcome_generation. NULL on members captured before m0186 and on U08 single-Request receipt members. U09c refuses to undo a member whose live counters have moved.'

''',

  r'''
COMMENT ON COLUMN public.attention_clear_operation_member.skip_reason IS 'Why a captured member was refused at apply time: the sweep reports it verbatim. NULL unless state is skipped or failed. Free text; the vocabulary belongs to the issuing unit, like attention_clear_operation.status.'

''',

  r'''
CREATE TABLE public.attention_cutover (
    id boolean DEFAULT true NOT NULL,
    cutover_at timestamp with time zone NOT NULL,
    legacy_seen_cursor text,
    legacy_seen_completed_at timestamp with time zone,
    obligation_key_cursor text,
    obligation_key_completed_at timestamp with time zone,
    placement_cursor text,
    placement_completed_at timestamp with time zone,
    CONSTRAINT attention_cutover__singleton_chk CHECK (id)
)
''',

  r'''
COMMENT ON TABLE public.attention_cutover IS 'U18a: the single row that fixes the attention cutover instant. Written once before any receipt is mutated; the backfill is restartable against it, so cutover_at is immutable and only the progress columns move.'

''',

  r'''
COMMENT ON COLUMN public.attention_cutover.cutover_at IS 'D19 fixed boundary. Set on the first backfill entry, before any row mutation, and never rewritten - a re-run that moved it would draw a different line than the pass it is resuming.'

''',

  r'''
COMMENT ON COLUMN public.attention_cutover.legacy_seen_cursor IS 'Last notification_outbox.id whose legacy_seen batch committed. A restart resumes after it. An optimisation over the NULL guard on every UPDATE, never a substitute: the guard alone makes a second pass a no-op.'

''',

  r'''
COMMENT ON COLUMN public.attention_cutover.legacy_seen_completed_at IS 'When the legacy_seen phase ran out of candidates. Set once; a later boot reads it and does no work at all.'

''',

  r'''
COMMENT ON COLUMN public.attention_cutover.obligation_key_cursor IS 'U18b gate 1: last notification_outbox.id the obligation-key pass considered - keyed, or left unkeyed because its identity was not derivable. Undecidable rows are walked past on purpose: nothing about a stored row makes it derivable later, and they stay counted in unrepairableObligationCount.'

''',

  r'''
COMMENT ON COLUMN public.attention_cutover.obligation_key_completed_at IS 'When gate 1 ran out of live unkeyed obligations created before the cutover. Set once.'

''',

  r'''
COMMENT ON COLUMN public.attention_cutover.placement_cursor IS 'U18b gate 2: last notification_outbox.id the placement pass demoted. Only provably timeline-only rows are candidates, so this cursor walks the decidable subset alone; every other pre-m0189 row keeps the placement the column default gave it.'

''',

  r'''
COMMENT ON COLUMN public.attention_cutover.placement_completed_at IS 'When gate 2 ran out of demotable rows. Set once.'

''',

  r'''
