  WHERE ((b.user_id IS NOT NULL) AND (b.status <> ALL (ARRAY[2, 3])) AND (b.published_at IS NOT NULL))
UNION ALL
 SELECT bs.beacon_id,
    bs.user_id
   FROM (public.beacon_steward bs
     JOIN public.beacon b ON ((b.id = bs.beacon_id)))
  WHERE ((b.status <> ALL (ARRAY[2, 3])) AND (b.published_at IS NOT NULL) AND (NOT public.block_hides(b.user_id, bs.user_id)))
UNION ALL
 SELECT bp.beacon_id,
    bp.user_id
   FROM (public.beacon_participant bp
     JOIN public.beacon b ON ((b.id = bp.beacon_id)))
  WHERE (((bp.role = 1) OR (bp.room_access = 3)) AND (b.status <> ALL (ARRAY[2, 3])) AND (b.published_at IS NOT NULL) AND (NOT public.block_hides(b.user_id, bp.user_id)))
