    seen_at timestamp with time zone,
    source_event_key text NOT NULL,
    destination_kind text NOT NULL,
    target_entity_id text,
    presentation_key text NOT NULL,
    presentation_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    in_app_preference_class text,
    suppression_class text DEFAULT 'standard'::text NOT NULL,
    access_policy text NOT NULL,
    requires_action boolean DEFAULT false NOT NULL,
    attention_thread_key text,
    settlement_kind text,
    settled_at timestamp with time zone,
    settled_by_user_id text,
    settled_by_occurrence_id text,
    occurrence_id text,
    cleared_at timestamp with time zone,
    clear_reason text,
    cleared_by_operation_id text,
    logical_task_key text,
    lifecycle_generation integer,
    placement text DEFAULT 'primary'::text NOT NULL,
    CONSTRAINT notification_outbox__access_policy_chk CHECK ((access_policy = ANY (ARRAY['beacon_content'::text, 'beacon_tombstone'::text, 'recipient_safe'::text, 'profile'::text]))),
    CONSTRAINT notification_outbox__beacon_policy_chk CHECK (((access_policy <> ALL (ARRAY['beacon_content'::text, 'beacon_tombstone'::text])) OR (beacon_id IS NOT NULL))),
    CONSTRAINT notification_outbox__clear_facts_chk CHECK ((((cleared_at IS NULL) AND (clear_reason IS NULL) AND (cleared_by_operation_id IS NULL)) OR ((cleared_at IS NOT NULL) AND (clear_reason IS NOT NULL)))),
    CONSTRAINT notification_outbox__clear_optional_only_chk CHECK (((NOT requires_action) OR ((cleared_at IS NULL) AND (clear_reason IS NULL) AND (cleared_by_operation_id IS NULL)))),
    CONSTRAINT notification_outbox__clear_reason_chk CHECK (((clear_reason IS NULL) OR (clear_reason = ANY (ARRAY['explicit'::text, 'request_open'::text, 'sweep'::text, 'legacy_seen'::text])))),
    CONSTRAINT notification_outbox__logical_task_chk CHECK (((requires_action OR ((logical_task_key IS NULL) AND (lifecycle_generation IS NULL))) AND ((lifecycle_generation IS NULL) OR (lifecycle_generation >= 0)))),
    CONSTRAINT notification_outbox__obligation_beacon_chk CHECK (((NOT requires_action) OR (beacon_id IS NOT NULL))),
    CONSTRAINT notification_outbox__placement_chk CHECK ((placement = ANY (ARRAY['primary'::text, 'timeline_only'::text]))),
    CONSTRAINT notification_outbox__preference_class_chk CHECK (((in_app_preference_class IS NULL) OR (suppression_class = 'noisy'::text))),
    CONSTRAINT notification_outbox__recipient_safe_chk CHECK (((access_policy <> 'recipient_safe'::text) OR ((presentation_key IS NOT NULL) AND (presentation_key = ANY (ARRAY['room_member_removed'::text, 'offer_declined'::text, 'offer_removed'::text]))))),
    CONSTRAINT notification_outbox__settlement_facts_chk CHECK ((((settlement_kind IS NULL) AND (settled_at IS NULL) AND (settled_by_user_id IS NULL) AND (settled_by_occurrence_id IS NULL)) OR ((settlement_kind IS NOT NULL) AND (settled_at IS NOT NULL)))),
    CONSTRAINT notification_outbox__settlement_kind_chk CHECK (((settlement_kind IS NULL) OR (settlement_kind = ANY (ARRAY['resolved'::text, 'dismissed'::text, 'superseded'::text, 'legacy_archived'::text, 'expired'::text])))),
    CONSTRAINT notification_outbox__settlement_obligation_chk CHECK (((settlement_kind IS NULL) OR requires_action)),
    CONSTRAINT notification_outbox__suppression_chk CHECK ((suppression_class = ANY (ARRAY['mandatory'::text, 'standard'::text, 'noisy'::text]))),
    CONSTRAINT notification_outbox__thread_key_chk CHECK ((((NOT requires_action) AND (attention_thread_key IS NULL)) OR (requires_action AND (attention_thread_key IS NOT NULL) AND (attention_thread_key ~ '^v1\|[^|]+\|[^|]+\|[^|]+$'::text) AND ((length(attention_thread_key) >= 5) AND (length(attention_thread_key) <= 512)))))
)
